      protection_how_rep_title: "விற்பனை பிரதிநிதி உங்களுக்காக ஆர்டரை உருவாக்கும்போது:",
      protection_how_rep_desc: "உங்கள் சவூதி தொழிற்சாலைகள் கணக்கு மூலம் பணம் செலுத்துங்கள். வங்கி பரிமாற்றம் மூலம் செலுத்தினால், அது சவூதி தொழிற்சாலைகளின் அதிகாரப்பூர்வ வங்கி கணக்கிற்கு அனுப்பப்படுவதை உறுதிசெய்யவும்.",
      protection_payments_desc1: "உங்களுக்கு பிடித்த உள்ளூர் கட்டண முறைகள், வங்கி பரிமாற்றங்கள் அல்லது ஒத்திவைக்கப்பட்ட கட்டண திட்டங்கள் மூலம் பணம் செலுத்துங்கள்.",
      protection_payments_desc2: "சவூதி தொழிற்சாலைகள் மூலம் செய்யப்படும் ஒவ்வொரு பரிவர்த்தனையும் SSL குறியாக்கம் மற்றும் தரவு பாதுகாப்பு நெறிமுறைகளால் பாதுகாக்கப்படுகிறது.",
      protection_payments_link: "பாதுகாப்பான கட்டண முறைகள் பற்றி அறியவும்",
      protection_delivery_desc1: "உங்கள் ஆர்டர் ஒரு நிர்ணயிக்கப்பட்ட, உத்தரவாதமான தேதியில் அனுப்பப்படும் அல்லது வழங்கப்படும் என்பதை அறிந்து உங்கள் சரக்கை சிறப்பாக திட்டமிட்டு நிர்வகிக்கவும்.",
